class Solution {int mod=1000000007,M;int[][] bit;int extend(int d,int x){if(bit[d]==null)bit[d]=new int[M/d+1];int[] tree=bit[d];int at=x/d;long ways=1;for(int i=at-1;i>0;i-=i&-i)ways+=tree[i];int value=(int)(ways%mod);for(int i=at;i<tree.length;i+=i&-i)tree[i]=(int)(((long)tree[i]+value)%mod);return value;}public int totalBeauty(int[] nums){for(int x:nums)M=Math.max(M,x);bit=new int[M+1][];int[] phi=new int[M+1];for(int i=1;i<=M;i++)phi[i]=i;for(int p=2;p<=M;p++)if(phi[p]==p)for(int j=p;j<=M;j+=p)phi[j]-=phi[j]/p;long ans=0;for(int x:nums)for(int d=1;d*d<=x;d++)if(x%d==0){ans=(ans+(long)phi[d]*extend(d,x))%mod;int other=x/d;if(other!=d)ans=(ans+(long)phi[other]*extend(other,x))%mod;}return (int)ans;}}